    22→
    23→    // 요청 데이터 로깅하는 로거
    24→    private static final Logger dataLogger = LoggerFactory.getLogger("INDEXING_DATA_LOGGER");
    25→    private static final Logger logger = LoggerFactory.getLogger(MainController.class);
    26→    private static final DateTimeFormatter timeFormat = DateTimeFormatter.ofPattern("HH:mm:ss");
    27→
    28→    /**
    29→     * @return json 결과
    30→     */
    31→    @RequestMapping({"/**"})
    32→    public ResponseEntity<?> indexing(@RequestBody String body, HttpServletRequest request) {
    33→        JsonResponse jsonResponse = new JsonResponse();
    34→        try {
    35→            if (!request.getMethod().equalsIgnoreCase("GET")) {
    36→                String service = request.getParameter("service");
    37→                String host = request.getHeader("Host");
    38→                //요청 json 에서는 개행문자를 모두 없앤다.
    39→                dataLogger.info(String.format("%s\t%s\t%s\t(\"host\":\"%s\",\"service\":\"%s\")\t%s",
    40→                        LocalDateTime.now().format(timeFormat),
    41→                        request.getMethod(),
    42→                        request.getRequestURI(), host, service, body.replaceAll("\r?\n", " ")));
    43→            } else {
    44→                logger.warn("Ignore GET request >> {} {}", request.getMethod(), request.getRequestURI());
    45→            }
    46→            jsonResponse.setDesc("");
    47→            jsonResponse.setResult(Boolean.TRUE);
    48→            jsonResponse.setStatus(HttpStatus.OK.value());
    49→            return ResponseEntity.ok(jsonResponse);
    50→        } catch (Exception e) {
    51→            logger.error("Error while logging data..", e);
    52→            return ResponseEntity.internalServerError().build();
    53→        }
    54→
    55→    }
    56→
    57→    @RequestMapping({"/_managements", "/_managements/*"})
    58→    public ResponseEntity<?> management(@RequestBody String body, HttpServletRequest request) {
    59→        logger.info("{} {}", request.getMethod(), request.getRequestURI());
    60→        JsonResponse jsonResponse = new JsonResponse();
    61→        jsonResponse.setStatus(HttpStatus.OK.value());
    62→        return ResponseEntity.ok(jsonResponse);
    63→    }
    64→
    65→}
