     3→import ch.qos.logback.core.rolling.DefaultTimeBasedFileNamingAndTriggeringPolicy;
     4→
     5→import java.util.Calendar;
     6→import java.util.Date;
     7→
     8→public class MinuteTriggeringPolicy<E> extends DefaultTimeBasedFileNamingAndTriggeringPolicy<E> {
     9→    protected int periodMinutes = 1;
    10→
    11→    public int getPeriodMinutes() {
    12→        return this.periodMinutes;
    13→    }
    14→
    15→    public void setPeriodMinutes(int minutes) {
    16→        if (minutes > 0) {
    17→            this.periodMinutes = minutes;
    18→        }
    19→    }
    20→
    21→    private long roundTimestamp(long time) {
    22→        int periodTicks = periodMinutes * 60000;
    23→        return periodTicks * (time / periodTicks);
    24→    }
    25→
    26→    @Override
    27→    public void setDateInCurrentPeriod(long now) {
    28→        dateInCurrentPeriod.setTime(roundTimestamp(now));
    29→    }
    30→
    31→    @Override
    32→    public void setDateInCurrentPeriod(Date _dateInCurrentPeriod) {
    33→        dateInCurrentPeriod = new Date(roundTimestamp(_dateInCurrentPeriod.getTime()));
    34→    }
    35→
    36→    @Override
    37→    public void computeNextCheck() {
    38→        rc.setTime(dateInCurrentPeriod);
    39→        rc.set(Calendar.SECOND, 0);
    40→        rc.set(Calendar.MILLISECOND, 0);
    41→        rc.add(Calendar.MINUTE, periodMinutes);
    42→
    43→        nextCheck = rc.getTime().getTime();
    44→    }
    45→
    46→    @Override
    47→    public String toString() {
    48→        return "MinuteTriggeringPolicy";
    49→    }
    50→}
